// Type: DecisionMaker.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum DecisionMaker {
    Task(DecisionTask),
    Party(DecisionParty),
}

// Record: DecisionMaker.
impl Record for DecisionMaker {
    type Limits = Limits;
    const TAIL: Path = paths::DECISION_MAKER_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 4)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 4)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Task(value) => { field::put(out, &[0], paths::DECISION_MAKER_TAG)?; value.write(limits, out) },
            Self::Party(value) => { field::put(out, &[1], paths::DECISION_MAKER_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::DECISION_MAKER_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Task(DecisionTask::read(limits, reader)?)),
            1 => Ok(Self::Party(DecisionParty::read(limits, reader)?)),
            2..=u8::MAX => Err(Problem { path: paths::DECISION_MAKER_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

