// Type: ObservabilityKind.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum ObservabilityKind {
    Incidents(ObservabilityKindIncidents),
    Incident(ObservabilityKindIncident),
    Panel(ObservabilityKindPanel),
    Result(ObservabilityKindResult),
    Effect(ObservabilityKindEffect),
    Outbox(ObservabilityKindOutbox),
    Hold(ObservabilityKindHold),
    Project(ObservabilityKindProject),
    Deployment,
}

// Record: ObservabilityKind.
impl Record for ObservabilityKind {
    type Limits = Limits;
    const TAIL: Path = paths::OBSERVABILITY_KIND_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 223)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 223)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Incidents(value) => { field::put(out, &[0], paths::OBSERVABILITY_KIND_TAG)?; value.write(limits, out) },
            Self::Incident(value) => { field::put(out, &[1], paths::OBSERVABILITY_KIND_TAG)?; value.write(limits, out) },
            Self::Panel(value) => { field::put(out, &[2], paths::OBSERVABILITY_KIND_TAG)?; value.write(limits, out) },
            Self::Result(value) => { field::put(out, &[3], paths::OBSERVABILITY_KIND_TAG)?; value.write(limits, out) },
            Self::Effect(value) => { field::put(out, &[4], paths::OBSERVABILITY_KIND_TAG)?; value.write(limits, out) },
            Self::Outbox(value) => { field::put(out, &[5], paths::OBSERVABILITY_KIND_TAG)?; value.write(limits, out) },
            Self::Hold(value) => { field::put(out, &[6], paths::OBSERVABILITY_KIND_TAG)?; value.write(limits, out) },
            Self::Project(value) => { field::put(out, &[7], paths::OBSERVABILITY_KIND_TAG)?; value.write(limits, out) },
            Self::Deployment => field::put(out, &[8], paths::OBSERVABILITY_KIND_TAG),
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::OBSERVABILITY_KIND_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Incidents(ObservabilityKindIncidents::read(limits, reader)?)),
            1 => Ok(Self::Incident(ObservabilityKindIncident::read(limits, reader)?)),
            2 => Ok(Self::Panel(ObservabilityKindPanel::read(limits, reader)?)),
            3 => Ok(Self::Result(ObservabilityKindResult::read(limits, reader)?)),
            4 => Ok(Self::Effect(ObservabilityKindEffect::read(limits, reader)?)),
            5 => Ok(Self::Outbox(ObservabilityKindOutbox::read(limits, reader)?)),
            6 => Ok(Self::Hold(ObservabilityKindHold::read(limits, reader)?)),
            7 => Ok(Self::Project(ObservabilityKindProject::read(limits, reader)?)),
            8 => Ok(Self::Deployment),
            9..=u8::MAX => Err(Problem { path: paths::OBSERVABILITY_KIND_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

