// Type: ObservabilityPurpose.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum ObservabilityPurpose {
    Call(ObservabilityPurposeCall),
    Procedure(ObservabilityPurposeProcedure),
    Projection(ObservabilityPurposeProjection),
}

// Record: ObservabilityPurpose.
impl Record for ObservabilityPurpose {
    type Limits = Limits;
    const TAIL: Path = paths::OBSERVABILITY_PURPOSE_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 274)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 274)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Call(value) => { field::put(out, &[0], paths::OBSERVABILITY_PURPOSE_TAG)?; value.write(limits, out) },
            Self::Procedure(value) => { field::put(out, &[1], paths::OBSERVABILITY_PURPOSE_TAG)?; value.write(limits, out) },
            Self::Projection(value) => { field::put(out, &[2], paths::OBSERVABILITY_PURPOSE_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::OBSERVABILITY_PURPOSE_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Call(ObservabilityPurposeCall::read(limits, reader)?)),
            1 => Ok(Self::Procedure(ObservabilityPurposeProcedure::read(limits, reader)?)),
            2 => Ok(Self::Projection(ObservabilityPurposeProjection::read(limits, reader)?)),
            3..=u8::MAX => Err(Problem { path: paths::OBSERVABILITY_PURPOSE_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

